UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"A prototype, notebook, personal API key or unofficial agent can reach production data, tools or services outside approved controls.","customer_symptom":"Operators discover experimental or unofficial AI components using real production endpoints, customer data, provider accounts or service credentials without the approved inventory, identity, network, logging or change-control path.","credible_failure_or_attack":"Developer or operator experimentation, unmanaged personal credentials, shadow AI deployment or environment misconfiguration can allow a prototype, notebook or unofficial agent to cross from an experimental context into production data or services outside normal governance and monitoring.","affected_assets":["production customer or business data","production service identities, API keys and credentials","production tools, APIs, databases and model or provider endpoints","approved environment and network boundaries","inventory, audit and change-control evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["organisations with decentralised AI adoption"],"threat_actor_or_failure_source":"developer or operator experimentation, unmanaged personal credentials, shadow AI deployment, environment misconfiguration or missing identity and network separation","trust_boundary":"The relevant trust boundary separates approved experimentation and sandbox environments from production identities, data stores, tools, networks and provider accounts; experimental components must not cross it except through an explicitly governed production path.","operational_impact":"An experimental or shadow agent reaching production can expose real data, exercise production authority, create untracked side effects and leave incomplete audit or ownership evidence. Operators may need to revoke credentials, isolate routes, investigate affected data and services, and hold production use until the boundary is restored and retested."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-11-03","change_triggers":["ARL-KB-012 experimentation, sandbox, production-boundary or enforcement change","ARL-KB-012 new agent, notebook, credential, provider, network route, data source or production service","ARL-KB-012 discovery of shadow AI usage, cross-environment access, bypass or incident evidence","ARL-KB-012 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='34c15fa58b33aa7c38fc0f55d2f457b60a02405dcbcba9c3853d1d0cde97a709', updated_at='2026-08-06' WHERE id='ARL-KB-012';
UPDATE risk_knowledge_checks SET objective='Determine whether experimental, shadow or unofficial AI components are prevented from reaching production data, credentials, tools and services outside approved governed paths.', method='Reconcile approved experimental environments, identities and providers with identity, network, billing, provider and audit logs to identify undeclared agent or model usage. Inspect the controls separating experimentation from production. In an owner-authorised non-production or production-equivalent test environment, verify that a prototype, notebook or unofficial-agent identity cannot authenticate to, route to or retrieve production-equivalent data and services through prohibited paths, while the approved sandbox workflow remains usable. Bind all observations to the exact assessed version and configuration.', check_types_json='["declared-control review","observed-control inspection","environment-boundary test","evidence review"]', required_evidence_json='["ARL-KB-012 assessed system, exact version, environment and experimental-versus-production scope","Approved environment, identity, credential, network and provider configuration defining the experimentation-to-production boundary","Identity, network, provider, billing or audit evidence showing which experimental agents, notebooks, credentials and endpoints were observed","Bounded positive evidence showing the approved experimental workflow operates only with authorised sandbox resources","Bounded negative evidence showing an experimental or unofficial identity cannot reach the prohibited production-equivalent data, credential, tool or service path","Tester identity, role, timestamp and evidence digest binding the observations to the assessed version"]', pass_condition='ARL-KB-012 passes only when approved experimental workflows remain confined to their authorised sandbox scope, no tested prototype, notebook, personal credential or unofficial-agent path can reach prohibited production-equivalent data or services, attempted boundary crossings are blocked or otherwise prevented before access occurs, and attributable version-bound evidence demonstrates the result.', fail_condition='ARL-KB-012 fails when an experimental or unofficial AI component can authenticate to, route to, retrieve from or act on prohibited production data or services; when personal or unmanaged credentials provide such access; when an undocumented exception bypasses the approved environment boundary; or when the claimed separation cannot be demonstrated with reproducible version-bound evidence.', limitations='This bounded assessment cannot prove that no dormant, transient or externally operated shadow agent exists outside the documented discovery sources. It evaluates only the stated environments, identities, providers, routes and exact assessed version and does not require access to real production customer data.', content_digest='df7892ad9dc5f60dc8dd51e04ac6edf11af4f1291b0d4973a3dd5c893f9c7d51', updated_at='2026-08-06' WHERE entry_id='ARL-KB-012';
UPDATE risk_knowledge_solutions SET control_objective='Prevent experimental or shadow AI components from reaching production data, credentials, tools or services outside governed and attributable paths, and make attempted boundary crossings visible.', recommended_remediation='Separate experimentation from production with distinct accounts, projects, networks and credentials; provide governed sandboxes with synthetic data; block unapproved providers and routes; prohibit personal credentials for production access; and rotate exposed shadow credentials after containment.', default_owner='Cloud and identity owner', priority='P1', implementation_principles_json='["ARL-KB-012: use distinct identities, credentials and network paths for experimental and production environments, with cross-environment access denied by default.","ARL-KB-012: provide governed experimentation environments with synthetic or explicitly approved data and no inherited production secrets or authority.","ARL-KB-012: version environment allowlists and access policies, record attempted boundary crossings, and require explicit governed promotion before experimental components receive production access."]', monitoring='Monitor identity, network, provider, billing and audit telemetry for experimental agents, notebooks, personal credentials, undeclared providers and cross-environment access attempts; alert the Cloud and identity owner on unexpected production routes, unmanaged credentials, policy drift or missing boundary evidence.', containment='Contain ARL-KB-012 by disabling the shadow or experimental route, revoking or rotating affected credentials, blocking the relevant production path, isolating impacted identities and preserving attributable network, identity, provider and audit evidence before re-enablement.', retest_acceptance_json='["ARL-KB-012: The exact remediated version preserves the documented separation between experimental and production identities, data, tools, networks and provider accounts.","ARL-KB-012: The approved experimental workflow completes successfully using only authorised sandbox resources and synthetic or explicitly approved test data.","ARL-KB-012: A dedicated simulated shadow or experimental identity cannot reach the documented prohibited production-equivalent data, credential, tool or service paths, and evidence of the boundary-crossing attempt is recorded.","ARL-KB-012: Reviewer identity, timestamp, assessed version, relevant configuration digests, known limitations and residual-risk or deployment decision are recorded."]', content_digest='485ce75f6109c665d05a9b6e8f4a72e03ece71678a9a85a8abccdae34bbdd69c', updated_at='2026-08-06' WHERE entry_id='ARL-KB-012';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='60e258f004b4c2b10b7a3a56b0e926b37ab04c9bdd6317b4d0113a49d40e1467', updated_at='2026-08-06' WHERE entry_id='ARL-KB-012';

